<?php
require __DIR__.'/includes/bootstrap.php';
$s=db()->prepare('SELECT p.*, c.name category_name, c.slug category_slug FROM products p JOIN categories c ON c.id=p.category_id WHERE p.id=? AND p.active=1');$s->execute([(int)($_GET['id']??0)]);$product=$s->fetch();if(!$product){http_response_code(404);$pageTitle='Peça não encontrada';include __DIR__.'/includes/header.php';echo '<main class="wrap page-shell"><h1 class="page-title">Esta peça já seguiu outro caminho.</h1><a href="'.e(app_url('index.php')).'">Voltar à curadoria ↗</a></main>';include __DIR__.'/includes/footer.php';exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$qty=max(1,(int)($_POST['quantity']??1));if($product['stock']<1){flash('Esta peça está esgotada.','error');}else{$_SESSION['cart'][$product['id']]=min((int)($_SESSION['cart'][$product['id']]??0)+$qty,(int)$product['stock']);flash('Peça adicionada ao seu carrinho.');}redirect(app_url('carrinho.php'));}
$pageTitle=$product['name'].' — ÉdoLeo';include __DIR__.'/includes/header.php';?>
<main class="wrap page-shell"><a class="text-link" href="<?=e(app_url('index.php#colecao'))?>">← Voltar à coleção</a><div class="detail-grid" style="margin-top:26px"><div class="detail-photo"><img src="<?=e($product['image'])?>" alt="<?=e($product['name'])?>"></div><div class="detail-copy"><span class="eyebrow"><?=e($product['brand']?:category_label($product['category_slug'],$product['category_name']))?></span><h1><?=e($product['name'])?></h1><span class="product-submeta"><?=e(category_label($product['category_slug'],$product['category_name']))?> · Peça pre-loved</span><div class="detail-price"><?=money($product['price'])?></div><p><?=nl2br(e($product['description']))?></p><p class="stock-note">✳ <?= (int)$product['stock']===1?'Última peça disponível':(int)$product['stock'].' unidades disponíveis' ?> · Peça única de acervo</p><form method="post" class="mt-4"><?=csrf_field()?><label class="form-label" for="quantity">Quantidade</label><div class="d-flex gap-2" style="max-width:340px"><input class="form-control" style="max-width:90px" type="number" id="quantity" name="quantity" min="1" max="<?= (int)$product['stock'] ?>" value="1" <?= (int)$product['stock']<1?'disabled':'' ?>><button class="button button-dark flex-grow-1 justify-content-between" <?= (int)$product['stock']<1?'disabled':'' ?>>Adicionar à sacola <span>↗</span></button></div></form></div></div></main>
